// n8n Code node: normalize incoming Call Aunty request
const item = $json;
const contact = item.contact ?? {};
return [{ json: {
  requestId: String(item.requestId ?? $execution.id),
  source: String(item.source ?? 'n8n'),
  intent: String(item.intent ?? 'unknown'),
  contact: { name: String(contact.name ?? ''), phone: String(contact.phone ?? ''), externalId: contact.externalId },
  consent: String(item.consent ?? 'unknown'),
  doNotContact: Boolean(item.doNotContact),
  survey: item.survey,
  context: item.context ?? {},
} }];

// n8n Code node: hard gate before CALL-E side effects
const x = $json;
const issues = [];
if (!x.contact?.phone) issues.push('MISSING_PHONE');
if (x.doNotContact) issues.push('CONTACT_IS_DNC');
if (x.consent !== 'granted') issues.push('CALL_CONSENT_NOT_GRANTED');
return [{ json: { ...x, allowed: issues.length === 0, policyIssues: issues } }];

// n8n Code node: build the CALL-E request without storing secrets in workflow data
const x = $json;
if (!x.allowed) return [{ json: { ...x, callePayload: null } }];
const questions = x.survey?.questions ?? [];
return [{ json: {
  ...x,
  callePayload: {
    to: x.contact.phone,
    contactName: x.contact.name,
    intent: x.intent,
    survey: questions.length ? { id: x.survey.id, questions } : undefined,
    metadata: { requestId: x.requestId, source: x.source }
  },
  idempotencyKey: `call-aunty:${x.requestId}`
} }];

// n8n Code node: request-id idempotency + same-day contact/intent dedupe
const DEDUPE_TTL_MS = 24 * 60 * 60 * 1000;
const x = $json;
const staticData = $getWorkflowStaticData('global');
staticData.calls = staticData.calls || {};
const now = Date.now();

for (const key of Object.keys(staticData.calls)) {
  const rec = staticData.calls[key];
  if (rec?.expiresAt && Date.parse(rec.expiresAt) <= now) delete staticData.calls[key];
}

const requestKey = `req:${x.requestId}`;
const contactWindowKey = `contact:${String(x.contact?.phone ?? '').replace(/\D/g, '')}:${x.intent}:${new Date(now).toISOString().slice(0, 10)}`;
const byRequest = staticData.calls[requestKey];
const byContact = staticData.calls[contactWindowKey];
const existing = byRequest || byContact;

if (existing) {
  return [{ json: {
    ...x,
    duplicate: true,
    duplicateKind: byRequest ? 'idempotency' : 'contact_window',
    requestKey,
    contactWindowKey,
    existingCall: existing,
  } }];
}

const pending = {
  status: 'pending',
  requestId: x.requestId,
  createdAt: new Date(now).toISOString(),
  expiresAt: new Date(now + DEDUPE_TTL_MS).toISOString(),
};
staticData.calls[requestKey] = pending;
staticData.calls[contactWindowKey] = pending;

return [{ json: { ...x, duplicate: false, requestKey, contactWindowKey } }];

// n8n Code node: decide whether a human must approve before CALL-E dispatch
const x = $json;
const ctx = x.context ?? {};
const skip = Boolean(ctx.autoApprove || ctx.skipApproval);
const resumeUrl = typeof $execution !== 'undefined' ? ($execution.resumeFormUrl || $execution.resumeUrl) : undefined;
return [{ json: {
  ...x,
  approval: {
    required: !skip,
    decision: skip ? 'not_required' : 'pending',
    reason: skip ? 'AUTO_APPROVE' : 'HUMAN_APPROVAL_REQUIRED',
    resumeUrl,
    summary: `Call ${x.contact?.name ?? 'unknown'} at ${x.contact?.phone ?? ''} for ${x.intent}.`,
  },
} }];

// n8n Code node: interpret Wait-form / webhook resume payload
const prior = $('Prepare Human Approval').first().json;
const incoming = $json;
const raw = String(incoming.Decision ?? incoming.decision ?? incoming.approval?.decision ?? '').toLowerCase().trim();
let decision = 'rejected';
if (raw === 'approve' || raw === 'approved') decision = 'approved';
else if (!raw) decision = 'timed_out';

if (decision !== 'approved') {
  const staticData = $getWorkflowStaticData('global');
  staticData.calls = staticData.calls || {};
  if (prior.requestKey) delete staticData.calls[prior.requestKey];
  if (prior.contactWindowKey) delete staticData.calls[prior.contactWindowKey];
}

return [{ json: {
  ...prior,
  approval: {
    ...prior.approval,
    decision,
    reason: decision === 'approved' ? 'OPERATOR_APPROVED' : decision === 'timed_out' ? 'APPROVAL_TIMED_OUT' : 'OPERATOR_REJECTED',
    approvedBy: incoming.Approver ?? incoming.approver,
    notes: incoming.Notes ?? incoming.notes,
  },
} }];

// n8n Code node: persist successful CALL-E ids for later dedupe hits
const payload = $('Prepare Human Approval').first().json;
const call = $json;
const staticData = $getWorkflowStaticData('global');
staticData.calls = staticData.calls || {};
const rec = {
  status: 'completed',
  requestId: payload.requestId,
  callId: call.callId ?? call.id,
  createdAt: new Date().toISOString(),
  expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
};
if (payload.requestKey) staticData.calls[payload.requestKey] = rec;
if (payload.contactWindowKey) staticData.calls[payload.contactWindowKey] = rec;
return [{ json: { ...payload, call, duplicate: false } }];

// n8n Code node: after HTTP retries are exhausted, classify and release pending locks
const prior = $('Prepare Human Approval').first().json;
const err = $json;
const staticData = $getWorkflowStaticData('global');
staticData.calls = staticData.calls || {};
if (prior.requestKey) delete staticData.calls[prior.requestKey];
if (prior.contactWindowKey) delete staticData.calls[prior.contactWindowKey];

const message = String(err.error?.message ?? err.message ?? JSON.stringify(err));
const status = Number(err.error?.httpCode ?? err.error?.statusCode ?? err.status ?? 0);
const retryable = status === 429 || status >= 500 || /429|timeout|temporar|network|fetch|econn|5\d\d/i.test(message);

return [{ json: {
  ...prior,
  retryExhausted: true,
  retryable,
  callError: { message, status },
} }];
